import csv
import json
import math
from collections import Counter
from datetime import datetime, timedelta, timezone
from pathlib import Path
from zoneinfo import ZoneInfo

import pandas as pd


DATA_DIR = Path("/app/dataset")
UTC = timezone.utc
REPORT_START = datetime(2024, 3, 15, 0, 0, tzinfo=UTC)
REPORT_END = datetime(2024, 3, 16, 0, 0, tzinfo=UTC)


def _parse_timestamp(value, timezone_name):
    if not isinstance(value, str) or not value.strip():
        return None
    value = value.strip()
    try:
        parsed = datetime.fromisoformat(value)
    except ValueError:
        try:
            parsed = datetime.strptime(value, "%d.%m.%Y %H:%M:%S")
        except ValueError:
            return None

    if parsed.tzinfo is not None:
        return parsed.astimezone(UTC)

    local_zone = ZoneInfo(timezone_name)
    first_fold = parsed.replace(tzinfo=local_zone, fold=0)
    second_fold = parsed.replace(tzinfo=local_zone, fold=1)
    # Ambiguous and nonexistent local times cannot be assigned an unambiguous UTC time.
    if first_fold.utcoffset() != second_fold.utcoffset():
        return None
    timestamp_utc = first_fold.astimezone(UTC)
    if timestamp_utc.astimezone(local_zone).replace(tzinfo=None) != parsed:
        return None
    return timestamp_utc


def _parse_number(value, delimiter):
    if not isinstance(value, str):
        return math.nan
    value = value.strip()
    if not value:
        return math.nan
    if delimiter == ";" and "," in value:
        value = value.replace(".", "").replace(",", ".")
    try:
        return float(value)
    except ValueError:
        return math.nan


def _local_window_to_utc(window, timezone_name):
    local_zone = ZoneInfo(timezone_name)
    start_local = datetime.fromisoformat(window[0]).replace(tzinfo=local_zone)
    end_local = datetime.fromisoformat(window[1]).replace(tzinfo=local_zone)
    return start_local.astimezone(UTC), end_local.astimezone(UTC)


def answer() -> dict[str, int]:
    calibration = json.loads((DATA_DIR / "sensors_calibration.json").read_text())[
        "enterprise_platform"
    ]["deployment_environments"]["system_config"]["farms"]

    farms = pd.read_csv(DATA_DIR / "farms.csv")
    registry = pd.read_csv(DATA_DIR / "farm_registry.csv")
    timezone_by_name = {
        str(row.farm_name).strip().lower(): row.timezone
        for row in farms.itertuples(index=False)
    }
    timezone_by_id = {
        row.farm_id: timezone_by_name[str(row.farm_name).strip().lower()]
        for row in registry.itertuples(index=False)
    }

    # Windows are represented in each site's local civil time and are half-open.
    maintenance_local = {
        "FARM_C": [("2024-03-16 08:00:00", "2024-03-16 12:00:00")],
        "FARM_F": [("2024-03-15 12:00:00", "2024-03-15 14:00:00")],
    }
    unit_to_kwh = {
        "kwh": 1.0,
        "mwh": 1000.0,
        "wh": 0.001,
        "btu": 0.0002930710701722222,
        "kw": 1.0,
    }

    result = {}
    for registry_row in registry.itertuples(index=False):
        farm_id = registry_row.farm_id
        timezone_name = timezone_by_id[farm_id]
        config = calibration[farm_id]
        calibration_data = config["calibration_data"]
        value_column = calibration_data["value_column_name"]
        offset = float(calibration_data["calibration_offset"])
        reading_type = config["sensor_info"]["reading_type"].lower()
        unit = config["sensor_info"]["unit"].strip().lower()
        conversion = unit_to_kwh[unit]

        path = DATA_DIR / f"production_{farm_id}.csv"
        raw_bytes = path.read_bytes()
        encoding = (
            "utf-16"
            if raw_bytes.startswith((b"\xff\xfe", b"\xfe\xff"))
            else "utf-8-sig"
        )
        lines = raw_bytes.decode(encoding).splitlines()
        header_line = lines[3]
        delimiter = ";" if ";" in header_line else ","
        headers = next(csv.reader([header_line], delimiter=delimiter))
        value_index = headers.index(value_column)

        # Parse as strings to handle both decimal conventions; resolve duplicate
        # observations at one instant by keeping the last record in file order.
        frame = pd.read_csv(
            path,
            skiprows=4,
            header=None,
            sep=delimiter,
            dtype=str,
            encoding=encoding,
            engine="python",
        )
        frame["_timestamp_utc"] = [
            _parse_timestamp(value, timezone_name) for value in frame.iloc[:, 0]
        ]
        frame = frame[frame["_timestamp_utc"].notna()].copy()
        frame = frame.drop_duplicates(subset=["_timestamp_utc"], keep="last")
        frame = frame.sort_values("_timestamp_utc")

        timestamps = [value.to_pydatetime() for value in frame["_timestamp_utc"]]
        intervals = [
            timestamps[index + 1] - timestamps[index]
            for index in range(len(timestamps) - 1)
            if timestamps[index + 1] > timestamps[index]
        ]
        sample_interval = Counter(intervals).most_common(1)[0][0] if intervals else timedelta(0)

        rows = []
        safety_spikes = []
        for (_, row), timestamp in zip(frame.iterrows(), timestamps):
            reading = _parse_number(row.iloc[value_index], delimiter)
            temperature = _parse_number(row.iloc[1], delimiter)
            rows.append((timestamp, reading))
            if math.isfinite(temperature) and temperature > 85.0:
                safety_spikes.append(timestamp)

        maintenance_windows = [
            _local_window_to_utc(window, timezone_name)
            for window in maintenance_local.get(farm_id, [])
        ]

        total_kwh = 0.0
        for timestamp, recorded_value in rows:
            if not (REPORT_START <= timestamp < REPORT_END):
                continue
            if any(
                spike < timestamp <= spike + timedelta(minutes=45)
                for spike in safety_spikes
            ):
                continue
            if any(start <= timestamp < end for start, end in maintenance_windows):
                continue
            if not math.isfinite(recorded_value):
                continue

            true_value = recorded_value - offset
            if true_value < 0:
                continue

            energy_kwh = true_value * conversion
            if reading_type == "power":
                energy_kwh *= sample_interval.total_seconds() / 3600.0
            total_kwh += energy_kwh

        result[farm_id] = int(round(total_kwh))

    return result


if __name__ == "__main__":
    with open("/app/answer.json", "w") as output_file:
        json.dump(answer(), output_file, default=list)

